import datetime
import json
import os
import pathlib
import time
import urllib.parse
import urllib.request

try:
    from zoneinfo import ZoneInfo
except ImportError:
    ZoneInfo = None


CACHE_VERSION = 2
FORCE_COOLDOWN_SECONDS = 5 * 60
RETRY_SECONDS = 15 * 60
INTERVAL_SECONDS = {
    "1h": 60 * 60,
    "3h": 3 * 60 * 60,
    "6h": 6 * 60 * 60,
    "12h": 12 * 60 * 60,
}


def fetch_json(url):
    request = urllib.request.Request(
        url,
        headers={"User-Agent": "NotchAny-Weather/1.2"},
    )
    with urllib.request.urlopen(request, timeout=12) as response:
        return json.load(response)


def enabled(key, default=True):
    value = os.environ.get("NOTCH_PARAM_" + key.upper())
    if value is None:
        return default
    return value == "1"


def value_at(values, index, default=None):
    return values[index] if index < len(values) else default


def short_time(value):
    if not value:
        return None
    return value.rsplit("T", 1)[-1][:5]


def beaufort(speed_kmh):
    if speed_kmh is None:
        return None
    thresholds = [1, 6, 12, 20, 29, 39, 50, 62, 75, 89, 103, 118]
    for level, threshold in enumerate(thresholds):
        if speed_kmh < threshold:
            return level
    return 12


def location_label(location):
    name = location.get("city") or location.get("region") or notch_t("ip_location")
    region = location.get("region") or ""
    country = location.get("country") or ""
    labels = [name]
    if region and name not in region and region not in name:
        labels.append(region)
    if country and all(country not in value and value not in country for value in labels):
        labels.append(country)
    return " · ".join(labels)


def ip_location(locale):
    language = "zh-CN" if locale.startswith("zh") else "en"
    location = fetch_json("https://ipwho.is/?" + urllib.parse.urlencode({"lang": language}))
    if not location.get("success"):
        raise ValueError(location.get("message") or notch_t("ip_location_failed"))
    return (
        float(location["latitude"]),
        float(location["longitude"]),
        location_label(location),
    )


def daily_aqi(latitude, longitude):
    query = urllib.parse.urlencode(
        {
            "latitude": latitude,
            "longitude": longitude,
            "hourly": "us_aqi",
            "timezone": "auto",
            "forecast_days": 7,
        }
    )
    response = fetch_json("https://air-quality-api.open-meteo.com/v1/air-quality?" + query)
    hourly = response.get("hourly") or {}
    times = hourly.get("time") or []
    values = hourly.get("us_aqi") or []
    maxima = {}
    for timestamp, raw_value in zip(times, values):
        if raw_value is None:
            continue
        date_key = timestamp.split("T", 1)[0]
        value = int(round(float(raw_value)))
        maxima[date_key] = max(maxima.get(date_key, value), value)
    return maxima


def fetch_forecast(latitude, longitude):
    daily_fields = [
        "weather_code",
        "temperature_2m_max",
        "temperature_2m_min",
        "precipitation_probability_max",
        "sunrise",
        "sunset",
        "wind_speed_10m_max",
        "wind_direction_10m_dominant",
    ]
    forecast_query = urllib.parse.urlencode(
        {
            "latitude": latitude,
            "longitude": longitude,
            "daily": ",".join(daily_fields),
            "temperature_unit": "celsius",
            "wind_speed_unit": "kmh",
            "timezone": "auto",
            "forecast_days": 7,
        }
    )
    forecast = fetch_json("https://api.open-meteo.com/v1/forecast?" + forecast_query)
    daily = forecast.get("daily") or {}
    dates = daily.get("time") or []
    codes = daily.get("weather_code") or []
    highs = daily.get("temperature_2m_max") or []
    lows = daily.get("temperature_2m_min") or []
    rain = daily.get("precipitation_probability_max") or []
    sunrise = daily.get("sunrise") or []
    sunset = daily.get("sunset") or []
    wind_speed = daily.get("wind_speed_10m_max") or []
    wind_direction = daily.get("wind_direction_10m_dominant") or []

    try:
        aqi = daily_aqi(latitude, longitude)
    except Exception:
        aqi = {}

    days = []
    for index, iso_date in enumerate(dates[:7]):
        date_value = datetime.date.fromisoformat(iso_date)
        speed = value_at(wind_speed, index)
        speed = None if speed is None else round(float(speed))
        direction = value_at(wind_direction, index)
        direction = None if direction is None else round(float(direction)) % 360
        days.append(
            {
                "date_iso": iso_date,
                "date": f"{date_value.month}/{date_value.day}",
                "code": int(value_at(codes, index, 0)),
                "high_c": round(float(value_at(highs, index, 0))),
                "low_c": round(float(value_at(lows, index, 0))),
                "rain": int(value_at(rain, index, 0) or 0),
                "sunrise": short_time(value_at(sunrise, index)),
                "sunset": short_time(value_at(sunset, index)),
                "wind_speed": speed,
                "wind_level": beaufort(speed),
                "wind_direction": direction,
                "aqi": aqi.get(iso_date),
            }
        )
    if len(days) != 7:
        raise ValueError(notch_t("incomplete_data"))
    return days, forecast.get("timezone") or ""


def timezone_now(timezone_name):
    if timezone_name and ZoneInfo is not None:
        try:
            return datetime.datetime.now(ZoneInfo(timezone_name))
        except Exception:
            pass
    return datetime.datetime.now().astimezone()


def cache_path(locale):
    safe_locale = "zh-Hans" if locale.startswith("zh") else "en"
    directory = pathlib.Path.home() / "Library" / "Caches" / "NotchAny" / "seven-day-weather"
    directory.mkdir(parents=True, exist_ok=True)
    return directory / ("forecast-" + safe_locale + ".json")


def load_cache(path):
    try:
        with path.open("r", encoding="utf-8") as handle:
            cache = json.load(handle)
        if cache.get("version") != CACHE_VERSION or len(cache.get("days") or []) != 7:
            return None
        return cache
    except Exception:
        return None


def save_cache(path, cache):
    temporary = path.with_suffix("." + str(os.getpid()) + ".tmp")
    with temporary.open("w", encoding="utf-8") as handle:
        json.dump(cache, handle, ensure_ascii=False, separators=(",", ":"))
    os.replace(temporary, path)


def next_refresh_at(cache, refresh_interval):
    if refresh_interval == "daily":
        current = timezone_now(cache.get("timezone") or "")
        tomorrow = current.date() + datetime.timedelta(days=1)
        boundary = datetime.datetime.combine(tomorrow, datetime.time.min, tzinfo=current.tzinfo)
        return boundary.timestamp()
    seconds = INTERVAL_SECONDS.get(refresh_interval, INTERVAL_SECONDS["3h"])
    return float(cache.get("fetched_at") or 0) + seconds


def cache_expired(cache, refresh_interval, now):
    if cache is None:
        return True
    if refresh_interval == "daily":
        current_date = timezone_now(cache.get("timezone") or "").date().isoformat()
        return current_date != cache.get("fetched_date")
    return now >= next_refresh_at(cache, refresh_interval)


def fetch_cache(locale):
    latitude, longitude, location = ip_location(locale)
    days, timezone_name = fetch_forecast(latitude, longitude)
    current = timezone_now(timezone_name)
    return {
        "version": CACHE_VERSION,
        "city": location,
        "days": days,
        "timezone": timezone_name,
        "fetched_at": time.time(),
        "fetched_date": current.date().isoformat(),
        "updated": current.strftime("%H:%M"),
        "sources": {
            "location": "ipwho.is",
            "weather": "Open-Meteo",
            "air": "Open-Meteo",
        },
    }


def display_temperature(value_c, unit_choice):
    if unit_choice == "f":
        return round(float(value_c) * 9 / 5 + 32)
    return round(float(value_c))


locale = os.environ.get("NOTCH_LOCALE") or "zh-Hans"
unit_choice = (os.environ.get("NOTCH_PARAM_UNIT") or "c").lower()
unit_symbol = "°F" if unit_choice == "f" else "°"
view_mode = (os.environ.get("NOTCH_PARAM_VIEW_MODE") or "week").lower()
refresh_interval = (os.environ.get("NOTCH_PARAM_REFRESH_INTERVAL") or "3h").lower()
visible = {
    "rain": enabled("show_rain"),
    "sun": enabled("show_sun"),
    "wind": enabled("show_wind"),
    "aqi": enabled("show_aqi"),
}

path = cache_path(locale)
cache = load_cache(path)
now = time.time()
event = os.environ.get("NOTCH_WIDGET_EVENT") or ""
force_requested = event == "force_refresh"
age = now - float((cache or {}).get("fetched_at") or 0)
force_allowed = force_requested and (cache is None or age >= FORCE_COOLDOWN_SECONDS)
should_fetch = cache_expired(cache, refresh_interval, now) or force_allowed
fetched_now = False
stale = False

if should_fetch:
    try:
        cache = fetch_cache(locale)
        save_cache(path, cache)
        fetched_now = True
    except Exception as error:
        if cache is None:
            state = {
                "city": notch_t("ip_location"),
                "error": notch_t("weather_data_failed"),
                "detail": str(error)[:120],
                "visible": visible,
                "view_mode": view_mode,
                "days": [],
                "next_refresh_at": int((now + RETRY_SECONDS) * 1000),
                "sources": {
                    "location": "ipwho.is",
                    "weather": "Open-Meteo",
                    "air": "Open-Meteo",
                },
            }
            notch_result(summary=notch_t("weather_update_failed"), widget=state)
            raise SystemExit(0)
        stale = True

display_days = []
for day in cache["days"][:1 if view_mode == "today" else 7]:
    item = dict(day)
    item["high"] = display_temperature(item.pop("high_c"), unit_choice)
    item["low"] = display_temperature(item.pop("low_c"), unit_choice)
    display_days.append(item)

next_refresh = now + RETRY_SECONDS if stale else next_refresh_at(cache, refresh_interval)
state = {
    "city": cache["city"],
    "unit": unit_symbol,
    "updated": cache["updated"],
    "visible": visible,
    "view_mode": view_mode,
    "refresh_interval": refresh_interval,
    "from_cache": not fetched_now,
    "stale": stale,
    "throttled": force_requested and not force_allowed,
    "next_refresh_at": int(next_refresh * 1000),
    "days": display_days,
    "sources": cache["sources"],
}
notch_result(summary=notch_t("weather_updated"), widget=state)

