:root {
  color-scheme: dark;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif;
  container-type: size;
}

* { box-sizing: border-box; }

html, body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: transparent;
  -webkit-user-select: none;
  user-select: none;
}

.weather {
  position: relative;
  width: 100%;
  height: 100%;
  padding: 8px 9px 9px;
  border-radius: 13px;
  background: rgba(255, 255, 255, .09);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .08);
  color: rgba(255, 255, 255, .94);
  display: grid;
  grid-template-rows: 22px minmax(0, 1fr);
  gap: 5px;
}

.topbar {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.location {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 6px;
}

.location-mark {
  width: 6px;
  height: 6px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: #71c8ff;
  box-shadow: 0 0 0 3px rgba(113, 200, 255, .12);
}

#city {
  max-width: 166px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11px;
  font-weight: 650;
}

.updated {
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 9px;
  color: rgba(255, 255, 255, .42);
  white-space: nowrap;
}

.toolbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 1px;
}

.source-info,
.refresh {
  width: 22px;
  height: 22px;
  flex: 0 0 auto;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: rgba(255, 255, 255, .58);
  cursor: pointer;
}

.source-info {
  position: relative;
  font: 13px/22px -apple-system, BlinkMacSystemFont, sans-serif;
}

.source-info::after {
  content: attr(data-tooltip);
  position: absolute;
  z-index: 5;
  top: 25px;
  right: 0;
  width: 168px;
  padding: 7px 8px;
  border-radius: 7px;
  background: rgb(35, 35, 38);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .10), 0 5px 14px rgba(0, 0, 0, .35);
  color: rgba(255, 255, 255, .86);
  font: 9px/1.45 -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif;
  text-align: left;
  white-space: pre-line;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-2px);
}

.source-info:hover::after,
.source-info:focus::after,
.source-info.show-source::after {
  opacity: 1;
  transform: translateY(0);
}

.source-info:hover,
.source-info:focus,
.source-info.show-source,
.refresh:hover { background: rgba(255, 255, 255, .10); color: #fff; }

.refresh { font: 15px/22px -apple-system, BlinkMacSystemFont, sans-serif; }
.refresh:active { background: rgba(255, 255, 255, .17); }
.refresh:disabled { cursor: default; opacity: .45; }
.refresh.busy { animation: spin .8s linear infinite; }

@keyframes spin { to { transform: rotate(360deg); } }

.forecast {
  min-width: 0;
  min-height: 0;
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  align-items: stretch;
}

.day {
  min-width: 0;
  padding: 2px 4px;
  border-left: 1px solid rgba(255, 255, 255, .07);
  display: grid;
  grid-template-rows: 12px 25px minmax(0, 1fr);
  align-items: center;
  justify-items: center;
  overflow: hidden;
}

.day:first-child { border-left: 0; }
.day.today { background: rgba(113, 200, 255, .08); border-radius: 7px; }

.day-head {
  width: 100%;
  min-width: 0;
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 3px;
  white-space: nowrap;
}

.weekday {
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 9px;
  font-weight: 650;
  color: rgba(255, 255, 255, .78);
}

.date { font-size: 7px; color: rgba(255, 255, 255, .36); }

.summary {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  min-width: 0;
}

.condition {
  flex: 0 0 auto;
  font-size: 17px;
  line-height: 1;
  filter: saturate(.9);
}

.temps {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  line-height: 10px;
}

.high { font-size: 10px; font-weight: 650; }
.low { font-size: 8px; color: rgba(255, 255, 255, .42); }
.condition-label { display: none; }

.metrics {
  width: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0;
  overflow: hidden;
}

.metric {
  max-width: 100%;
  height: 10px;
  overflow: hidden;
  text-overflow: ellipsis;
  color: rgba(255, 255, 255, .54);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1px;
  font-size: 7px;
  line-height: 10px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.metric::before {
  width: 8px;
  flex: 0 0 auto;
  text-align: center;
  font-size: 8px;
}

.metric.rain { color: rgba(113, 200, 255, .84); }
.metric.rain::before { content: "☂"; }
.metric.sun { color: rgba(255, 205, 107, .82); }
.metric.sun::before { content: "☀"; }
.metric.wind { color: rgba(188, 223, 236, .78); }
.metric.wind::before { content: "≋"; }
.metric.aqi::before { content: "◉"; }
.metric.aqi.good { color: rgba(99, 214, 146, .86); }
.metric.aqi.moderate { color: rgba(245, 201, 92, .88); }
.metric.aqi.unhealthy { color: rgba(255, 139, 91, .90); }
.metric.aqi.hazardous { color: rgba(224, 112, 160, .90); }

.forecast.single {
  grid-template-columns: minmax(0, 1fr);
}

.single-day {
  padding: 4px 12px;
  border-left: 0;
  background: rgba(113, 200, 255, .055);
  border-radius: 8px;
  grid-template-columns: 68px 108px minmax(0, 1fr);
  grid-template-rows: minmax(0, 1fr);
  justify-items: stretch;
}

.single-day .day-head {
  height: 100%;
  padding-right: 12px;
  border-right: 1px solid rgba(255, 255, 255, .08);
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 3px;
}

.single-day .weekday { font-size: 13px; color: rgba(255, 255, 255, .94); }
.single-day .date { display: block; font-size: 9px; }

.single-day .summary {
  justify-content: flex-start;
  gap: 9px;
  padding-left: 12px;
}

.single-day .condition { font-size: 36px; }
.single-day .temps { line-height: 15px; }
.single-day .high { font-size: 21px; }
.single-day .low { font-size: 11px; }
.single-day .condition-label {
  display: block;
  max-width: 82px;
  overflow: hidden;
  text-overflow: ellipsis;
  color: rgba(255, 255, 255, .62);
  font-size: 9px;
  line-height: 11px;
}

.single-day .metrics {
  padding-left: 14px;
  border-left: 1px solid rgba(255, 255, 255, .08);
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-auto-rows: 22px;
  align-content: center;
  gap: 1px 10px;
}

.single-day .metric {
  max-width: none;
  height: 22px;
  justify-content: flex-start;
  border-bottom: 1px solid rgba(255, 255, 255, .055);
  font-size: 10px;
  line-height: 22px;
}

.single-day .metric::before {
  width: 14px;
  font-size: 12px;
}

.single-day.no-metrics { grid-template-columns: 82px minmax(0, 1fr); }
.single-day.no-metrics .summary { justify-content: center; }
.single-day.no-metrics .metrics { display: none; }

.message {
  min-width: 0;
  min-height: 0;
  border-radius: 8px;
  background: rgba(255, 255, 255, .05);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  text-align: center;
  padding: 10px;
}

.message[hidden] { display: none; }
.message strong { font-size: 11px; font-weight: 650; }
.message span { max-width: 90%; font-size: 9px; color: rgba(255, 255, 255, .45); overflow-wrap: anywhere; }

@container (min-height: 170px) {
  .day:not(.single-day) {
    grid-template-rows: 16px 40px auto;
    align-content: center;
    gap: 4px;
  }

  .day:not(.single-day) .weekday { font-size: 10px; }
  .day:not(.single-day) .date { font-size: 8px; }
  .day:not(.single-day) .condition { font-size: 22px; }
  .day:not(.single-day) .temps { line-height: 12px; }
  .day:not(.single-day) .high { font-size: 13px; }
  .day:not(.single-day) .low { font-size: 10px; }
  .day:not(.single-day) .metrics { gap: 1px; }
  .day:not(.single-day) .metric {
    height: 13px;
    font-size: 8px;
    line-height: 13px;
  }
}

@container (max-width: 330px) {
  .weather { padding-left: 6px; padding-right: 6px; }
  .day { padding-left: 2px; padding-right: 2px; }
  .condition { font-size: 15px; }
  .metric { font-size: 6.5px; }
  .date { display: none; }
  .single-day { grid-template-columns: 56px 92px minmax(0, 1fr); }
  .single-day .condition { font-size: 29px; }
  .single-day .high { font-size: 18px; }
  .single-day .metric { font-size: 9px; }
}

@media (prefers-reduced-motion: reduce) {
  .refresh.busy { animation: none; }
}

