(function () {
  "use strict";

  var i18n = (window.__notchWidget && window.__notchWidget.i18n) || {};
  var weather = document.getElementById("weather");
  var city = document.getElementById("city");
  var updated = document.getElementById("updated");
  var forecast = document.getElementById("forecast");
  var sourceInfo = document.getElementById("sourceInfo");
  var refreshButton = document.getElementById("refresh");
  var message = document.getElementById("message");
  var messageTitle = document.getElementById("messageTitle");
  var messageDetail = document.getElementById("messageDetail");
  var timer = null;

  function t(key) {
    return i18n[key] || key;
  }

  function format(key, values) {
    return t(key).replace(/\{([a-z_]+)\}/g, function (_, name) {
      return values[name] === undefined || values[name] === null ? "--" : String(values[name]);
    });
  }

  function applyStaticText() {
    weather.setAttribute("aria-label", t("widget_label"));
    city.textContent = t("ip_location");
    updated.textContent = t("updating");
    sourceInfo.setAttribute("aria-label", t("view_sources"));
    sourceInfo.title = t("view_sources");
    refreshButton.setAttribute("aria-label", t("refresh_weather"));
    refreshButton.title = t("refresh_weather");
  }

  function conditionFor(code) {
    if (code === 0) return { icon: "☀️", key: "condition_clear" };
    if (code === 1 || code === 2) return { icon: "🌤️", key: "condition_partly_cloudy" };
    if (code === 3) return { icon: "☁️", key: "condition_cloudy" };
    if (code === 45 || code === 48) return { icon: "🌫️", key: "condition_fog" };
    if (code >= 51 && code <= 57) return { icon: "🌦️", key: "condition_drizzle" };
    if (code >= 61 && code <= 67) return { icon: "🌧️", key: "condition_rain" };
    if (code >= 71 && code <= 77) return { icon: "🌨️", key: "condition_snow" };
    if (code >= 80 && code <= 82) return { icon: "🌦️", key: "condition_showers" };
    if (code === 85 || code === 86) return { icon: "🌨️", key: "condition_snow_showers" };
    if (code >= 95) return { icon: "⛈️", key: "condition_thunderstorm" };
    return { icon: "☁️", key: "condition_weather" };
  }

  function textNode(className, value, title) {
    var node = document.createElement("span");
    node.className = className;
    node.textContent = value;
    if (title) node.title = title;
    return node;
  }

  function weekdayFor(dateIso, index) {
    if (index === 0) return t("today");
    var weekdayKeys = [
      "weekday_sun", "weekday_mon", "weekday_tue", "weekday_wed",
      "weekday_thu", "weekday_fri", "weekday_sat"
    ];
    var parts = String(dateIso || "").split("-").map(Number);
    if (parts.length !== 3) return "--";
    var day = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2])).getUTCDay();
    return t(weekdayKeys[day]);
  }

  function windDirection(degrees) {
    if (degrees === null || degrees === undefined) return "--";
    var keys = ["dir_n", "dir_ne", "dir_e", "dir_se", "dir_s", "dir_sw", "dir_w", "dir_nw"];
    return t(keys[Math.round(Number(degrees) / 45) % 8]);
  }

  function aqiClass(value) {
    if (value === null || value === undefined) return "moderate";
    if (value <= 50) return "good";
    if (value <= 100) return "moderate";
    if (value <= 200) return "unhealthy";
    return "hazardous";
  }

  function unwrap(value) {
    if (!value) return null;
    if (value.ok && value.state) return value.state;
    if (value.state && (value.state.days || value.state.error)) return value.state;
    if (value.days || value.error) return value;
    return null;
  }

  function addMetric(container, className, text, title) {
    container.appendChild(textNode("metric " + className, text, title));
  }

  function clearTimer() {
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function scheduleNext(state) {
    clearTimer();
    if (!notchany.visible || !state || !state.next_refresh_at) return;
    var delay = Math.max(60 * 1000, Number(state.next_refresh_at) - Date.now());
    timer = setTimeout(function () {
      refresh(false);
    }, delay);
  }

  function render(value) {
    var state = unwrap(value);
    if (!state) return false;

    city.textContent = state.city || t("ip_location");
    var sources = state.sources || {};
    var sourceLines = [
      format("source_location", { source: sources.location || "ipwho.is" }),
      format("source_weather", { source: sources.weather || "Open-Meteo" })
    ];
    if (state.visible && state.visible.aqi) {
      sourceLines.push(format("source_air", { source: sources.air || "Open-Meteo" }));
    }
    sourceInfo.dataset.tooltip = sourceLines.join("\n");

    if (state.error) {
      forecast.hidden = true;
      message.hidden = false;
      messageTitle.textContent = state.error;
      messageDetail.textContent = state.detail || t("retry_later");
      updated.textContent = "";
      scheduleNext(state);
      return true;
    }

    var days = state.days || [];
    if (!days.length) return false;

    var visible = state.visible || {};
    var metricCount = [visible.rain, visible.sun, visible.wind, visible.aqi].filter(Boolean).length;
    var single = state.view_mode === "today" || days.length === 1;
    forecast.classList.toggle("single", single);
    var fragment = document.createDocumentFragment();

    days.forEach(function (day, index) {
      var info = conditionFor(day.code);
      var condition = t(info.key);
      var weekday = weekdayFor(day.date_iso, index);
      var item = document.createElement("article");
      item.className = "day" + (index === 0 ? " today" : "") + (single ? " single-day" : "");
      if (single && metricCount === 0) item.classList.add("no-metrics");

      var head = document.createElement("div");
      head.className = "day-head";
      head.appendChild(textNode("weekday", weekday));
      head.appendChild(textNode("date", day.date));
      item.appendChild(head);

      var summary = document.createElement("div");
      summary.className = "summary";
      summary.appendChild(textNode("condition", info.icon, condition));
      var temps = document.createElement("div");
      temps.className = "temps";
      temps.appendChild(textNode("high", day.high + state.unit));
      temps.appendChild(textNode("low", day.low + state.unit));
      temps.appendChild(textNode("condition-label", condition));
      summary.appendChild(temps);
      item.appendChild(summary);

      var metrics = document.createElement("div");
      metrics.className = "metrics";
      var details = [weekday, condition, day.high + state.unit + "/" + day.low + state.unit];

      if (visible.rain) {
        var rainTitle = format("rain_detail", { value: day.rain });
        addMetric(metrics, "rain", day.rain + "%", rainTitle);
        details.push(rainTitle);
      }
      if (visible.sun) {
        var sunrise = day.sunrise || "--";
        var sunset = day.sunset || "--";
        var sunTitle = format("sun_detail", { sunrise: sunrise, sunset: sunset });
        addMetric(metrics, "sun", sunrise + "/" + sunset, sunTitle);
        details.push(sunTitle);
      }
      if (visible.wind) {
        var direction = windDirection(day.wind_direction);
        var windShort = format("wind_level_short", { direction: direction, level: day.wind_level });
        var windTitle = format("wind_detail", {
          direction: direction,
          level: day.wind_level,
          speed: day.wind_speed
        });
        addMetric(metrics, "wind", windShort, windTitle);
        details.push(windTitle);
      }
      if (visible.aqi) {
        var aqiValue = day.aqi === null || day.aqi === undefined ? "--" : day.aqi;
        var aqiTitle = day.aqi === null || day.aqi === undefined
          ? t("aqi_unavailable")
          : format("aqi_detail", { value: day.aqi });
        addMetric(metrics, "aqi " + aqiClass(day.aqi), "AQI " + aqiValue, aqiTitle);
        details.push(aqiTitle);
      }

      item.appendChild(metrics);
      item.title = details.join(" · ");
      fragment.appendChild(item);
    });

    forecast.replaceChildren(fragment);
    forecast.hidden = false;
    message.hidden = true;
    updated.textContent = format(state.stale ? "cached" : "updated", {
      time: state.updated || t("just_now")
    });
    scheduleNext(state);
    return true;
  }

  function setBusy(busy) {
    refreshButton.disabled = busy;
    refreshButton.classList.toggle("busy", busy);
  }

  function refresh(force) {
    if (!notchany.visible) return Promise.resolve();
    setBusy(true);
    return notchany.invoke(force ? "force_refresh" : "refresh", null)
      .then(function (result) {
        if (!render(result) && !notchany.state) updated.textContent = t("no_data");
      })
      .catch(function () {
        updated.textContent = t("refresh_failed");
      })
      .finally(function () {
        setBusy(false);
      });
  }

  applyStaticText();
  refreshButton.addEventListener("click", function () {
    refresh(true);
  });
  sourceInfo.addEventListener("click", function () {
    sourceInfo.classList.toggle("show-source");
  });
  notchany.addEventListener("statechange", function (event) {
    render(event.state || notchany.state);
  });
  notchany.addEventListener("visibilitychange", function () {
    clearTimer();
    if (notchany.visible) refresh(false);
  });

  if (notchany.state) render(notchany.state);
  if (notchany.visible) refresh(false);
})();
